def tracked_files(context: ApplicationContext, *args) -> list[str]:
    """Return the names of all files in the repository"""
    out = context.git.ls_files('--', *args, z=True, _readonly=True)[STDOUT]
    if out:
        return sorted(out[:-1].split('\0'))
    return []


